<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Falling Sand Sandbox</title>
<style>
  :root {
    --bg: #101318;
    --panel: #1a1f27;
    --panel2: #222936;
    --text: #e9eef5;
    --muted: #9da8b8;
    --accent: #8ab4f8;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    color: var(--text);
    background:
      radial-gradient(circle at 50% -10%, #263244 0, transparent 45%),
      var(--bg);
    font-family: system-ui, -apple-system, Segoe UI, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
  }
  .app {
    width: min(94vw, 760px);
    padding: 24px 18px 28px;
    text-align: center;
  }
  h1 {
    margin: 0 0 5px;
    font-size: clamp(1.35rem, 4vw, 2rem);
    letter-spacing: .04em;
    font-weight: 700;
  }
  .subtitle {
    color: var(--muted);
    margin-bottom: 18px;
    font-size: .92rem;
  }
  .stage {
    display: flex;
    justify-content: center;
    filter: drop-shadow(0 15px 30px rgba(0,0,0,.45));
  }
  canvas {
    width: 600px;
    height: 600px;
    max-width: 92vw;
    max-height: 92vw;
    display: block;
    background: #080a0d;
    border: 2px solid #394453;
    border-radius: 8px;
    image-rendering: pixelated;
    touch-action: none;
    cursor: crosshair;
  }
  .toolbar {
    margin: 18px auto 0;
    padding: 12px;
    max-width: 600px;
    background: rgba(26,31,39,.94);
    border: 1px solid #303a49;
    border-radius: 12px;
    display: flex;
    gap: 9px;
    justify-content: center;
    align-items: center;
    flex-wrap: wrap;
  }
  button {
    border: 0;
    border-radius: 7px;
    padding: 10px 14px;
    color: #eaf1fb;
    background: var(--panel2);
    box-shadow: 0 2px 4px rgba(0,0,0,.3), inset 0 1px rgba(255,255,255,.06);
    font: inherit;
    font-size: .9rem;
    cursor: pointer;
    transition: transform .1s, background .15s, box-shadow .15s;
  }
  button:hover { background: #303a4b; }
  button:active { transform: translateY(1px); }
  button.active {
    background: #3d5f91;
    box-shadow: 0 0 0 2px #8ab4f8, 0 3px 8px rgba(0,0,0,.35);
  }
  #clear {
    background: #713c49;
    margin-left: 7px;
  }
  #clear:hover { background: #8d4858; }
  .hint {
    margin-top: 12px;
    color: var(--muted);
    font-size: .8rem;
  }
</style>
</head>
<body>
<main class="app">
  <h1>Falling Sand</h1>
  <div class="subtitle">Paint materials into the miniature world</div>

  <div class="stage">
    <canvas id="sand" width="600" height="600" aria-label="Falling sand simulation"></canvas>
  </div>

  <div class="toolbar">
    <button id="mat-sand" data-material="sand">Sand</button>
    <button id="mat-water" data-material="water">Water</button>
    <button id="mat-wall" data-material="wall">Wall</button>
    <button id="mat-acid" data-material="acid">Acid</button>
    <button id="mat-empty" data-material="empty">Eraser</button>
    <button id="clear">Clear</button>
  </div>
  <div class="hint">Drag on the canvas to paint · sand sinks through liquids · acid eats sand and walls</div>
</main>

<script>
(() => {
  "use strict";

  const canvas = document.getElementById("sand");
  const ctx = canvas.getContext("2d");
  const w = 100, h = 100;
  const cells = new Array(w * h).fill("empty");
  const moved = new Uint32Array(w * h);
  let stepNumber = 0;
  let selected = "sand";
  let drawing = false;
  let seed = 0x51f15e;

  const colors = {
    empty: "#080a0d",
    sand: "#e7bb62",
    water: "#4b9fe8",
    wall: "#727b88",
    acid: "#b8e84d"
  };

  function index(x, y) { return y * w + x; }
  function inside(x, y) { return x >= 0 && x < w && y >= 0 && y < h; }

  function randomBit() {
    seed = (seed * 1664525 + 1013904223) >>> 0;
    return (seed >>> 30) & 1;
  }

  function swap(x1, y1, x2, y2) {
    const a = index(x1, y1), b = index(x2, y2);
    const t = cells[a];
    cells[a] = cells[b];
    cells[b] = t;
    moved[a] = stepNumber;
    moved[b] = stepNumber;
  }

  function move(x1, y1, x2, y2) {
    const a = index(x1, y1), b = index(x2, y2);
    cells[b] = cells[a];
    cells[a] = "empty";
    moved[a] = stepNumber;
    moved[b] = stepNumber;
  }

  function dissolveAround(x, y) {
    const neighbors = [[x, y + 1], [x - 1, y], [x + 1, y]];
    for (const [nx, ny] of neighbors) {
      if (!inside(nx, ny)) continue;
      const v = cells[index(nx, ny)];
      if (v === "sand" || v === "wall") cells[index(nx, ny)] = "empty";
    }
  }

  function tryLiquid(x, y, kind) {
    const below = y + 1;
    if (below < h && cells[index(x, below)] === "empty") {
      move(x, y, x, below);
      return true;
    }

    const first = randomBit() ? -1 : 1;
    const dirs = [first, -first];
    for (const dx of dirs) {
      const nx = x + dx;
      if (inside(nx, y) && cells[index(nx, y)] === "empty") {
        move(x, y, nx, y);
        return true;
      }
    }
    return false;
  }

  function updateSand(x, y) {
    if (y + 1 >= h) return;
    const below = cells[index(x, y + 1)];

    if (below === "empty") {
      move(x, y, x, y + 1);
      return;
    }

    if (below === "water" || below === "acid") {
      // Prefer pushing the liquid sideways. This prevents a falling column
      // from transporting liquid upward through the column.
      const first = randomBit() ? -1 : 1;
      for (const dx of [first, -first]) {
        const nx = x + dx;
        if (inside(nx, y + 1) && cells[index(nx, y + 1)] === "empty") {
          cells[index(nx, y + 1)] = below;
          cells[index(x, y + 1)] = "sand";
          cells[index(x, y)] = "empty";
          moved[index(nx, y + 1)] = stepNumber;
          moved[index(x, y + 1)] = stepNumber;
          moved[index(x, y)] = stepNumber;
          return;
        }
      }
      // In a fully enclosed pocket, use the specified sinking swap.
      swap(x, y, x, y + 1);
      return;
    }

    const first = randomBit() ? -1 : 1;
    for (const dx of [first, -first]) {
      const nx = x + dx;
      if (inside(nx, y + 1) && cells[index(nx, y + 1)] === "empty") {
        move(x, y, nx, y + 1);
        return;
      }
    }
  }

  function updateCell(x, y) {
    const id = index(x, y);
    if (moved[id] === stepNumber) return;
    const material = cells[id];

    if (material === "wall" || material === "empty") return;

    if (material === "acid") {
      dissolveAround(x, y);
      tryLiquid(x, y, "acid");
    } else if (material === "water") {
      tryLiquid(x, y, "water");
    } else if (material === "sand") {
      updateSand(x, y);
    }
  }

  function advanceOne() {
    stepNumber++;
    // Bottom row upward is essential: each particle gets at most one move.
    for (let y = h - 1; y >= 0; y--) {
      for (let x = 0; x < w; x++) updateCell(x, y);
    }
  }

  function render() {
    const image = ctx.createImageData(w, h);
    for (let i = 0; i < cells.length; i++) {
      const hex = colors[cells[i]];
      const r = parseInt(hex.slice(1, 3), 16);
      const g = parseInt(hex.slice(3, 5), 16);
      const b = parseInt(hex.slice(5, 7), 16);
      image.data[i * 4] = r;
      image.data[i * 4 + 1] = g;
      image.data[i * 4 + 2] = b;
      image.data[i * 4 + 3] = 255;
    }
    ctx.imageSmoothingEnabled = false;
    ctx.putImageData(image, 0, 0);
  }

  function clear() {
    cells.fill("empty");
    render();
  }

  function setCell(x, y, material) {
    if (inside(x, y) &&
        ["empty", "sand", "water", "wall", "acid"].includes(material)) {
      cells[index(x, y)] = material;
    }
  }

  function tick(n = 1) {
    n = Math.max(0, Math.floor(Number(n) || 0));
    for (let i = 0; i < n; i++) advanceOne();
    render();
  }

  window.sim = { w, h, tick, get: (x, y) =>
    inside(x, y) ? cells[index(x, y)] : "empty", set: setCell, clear };

  document.querySelectorAll("[data-material]").forEach(button => {
    button.addEventListener("click", () => {
      selected = button.dataset.material;
      document.querySelectorAll("[data-material]").forEach(b =>
        b.classList.toggle("active", b === button)
      );
    });
  });
  document.getElementById("mat-sand").classList.add("active");
  document.getElementById("clear").addEventListener("click", clear);

  function paint(event) {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((event.clientX - rect.left) / rect.width * w);
    const y = Math.floor((event.clientY - rect.top) / rect.height * h);
    const radius = 1;
    for (let dy = -radius; dy <= radius; dy++) {
      for (let dx = -radius; dx <= radius; dx++) {
        if (dx * dx + dy * dy <= radius * radius) setCell(x + dx, y + dy, selected);
      }
    }
    render();
  }

  canvas.addEventListener("pointerdown", e => {
    drawing = true;
    canvas.setPointerCapture(e.pointerId);
    paint(e);
  });
  canvas.addEventListener("pointermove", e => { if (drawing) paint(e); });
  canvas.addEventListener("pointerup", () => drawing = false);
  canvas.addEventListener("pointercancel", () => drawing = false);

  function animate() {
    tick(1);
    requestAnimationFrame(animate);
  }
  render();
  requestAnimationFrame(animate);
})();
</script>
</body>
</html>
